head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > E > ongridmouseenter]<br/>GridView 컴포넌트 영역 내로 마우스 포인터가 들어왔을때 발생합니다.",
    "validation" : [
        "이벤트 핸들러에 MouseEvent 객체 e 가 전달됩니다.",
        "GridView 영역으로 마우스가 들어가면 [onheadermouseover/onbodymouseover] > ongridmouseenter 순서로 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - 발생 순서 관찰을 위해 onheadermouseover / onbodymouseover 도 함께 바인딩
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // dataList 생성 (Body 행 표시)
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // 현재 전제 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 단일 GridView.\n[절차] 마우스를 GridView 영역 밖에서 안으로 이동.\n[확인] 결과창 ▶ 순서가 [onheadermouseover/onbodymouseover] > ongridmouseenter 입니다."', '', 'label1');

    // 이벤트 바인딩 (ongridmouseenter + 순서 관찰용 onheadermouseover / onbodymouseover)
    let eList = $c.gcm.createEList(["ongridmouseenter", "onheadermouseover", "onbodymouseover"]);

    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" autoFit="allColumn" ' + eList + ' checkAllType="false" id="" style="width:560px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="ongridmouseenter 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        'target1',
        "gridView",
        strTarget,
        grp_comp
    );
}



// GridView 영역 안으로 마우스가 들어 왔을 때 발생
//  - 발생 즉시 한 줄(▶) 출력 → 결과창 라인 순서 = 실제 이벤트 발생 순서
//  - e 는 표준 MouseEvent 객체 → 한 줄로만 출력 (개별 속성 나열 금지)
scwin.target1_ongridmouseenter = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("▶ ongridmouseenter");
    wf_body_bottom.getObj("scwin").setReturnValue("e : " + e);
}



// Header Cell 영역으로 마우스가 들어 왔을 때 발생 (발생 순서 관찰용)
//  - 발생 즉시 한 줄(▶) 출력
scwin.target1_onheadermouseover = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("▶ onheadermouseover");
}



// Body Cell 영역으로 마우스가 들어 왔을 때 발생 (발생 순서 관찰용)
//  - 발생 즉시 한 줄(▶) 출력
scwin.target1_onbodymouseover = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("▶ onbodymouseover");
}
